class Item {
  final String name;
  final double price;
  final int qty;

  const Item(this.name, this.price, this.qty);
}

const cart = [Item('usb-c', 12.0, 5), Item('dock', 40.0, 1)];

workspace.pricing.dart:
import 'cart.dart';

double subtotal(List<Item> items) =>
    items.fold(0, (sum, it) => sum + it.price * it.qty);

/// Apply a 10% promotional discount.
double discounted(double amount) => amount * 0.9;

/// Add 5% sales tax.
double taxed(double amount) => amount * 1.05;

double total(List<Item> items) => taxed(taxed(discounted(subtotal(items))));
